// "Pick a display name" card for guests — NOT generated by Figma Make.
import { useState } from "react";
import "./Supabase.css";

export default function DisplayNamePrompt({
  onSave,
  onSkip,
}: {
  onSave: (name: string) => Promise<boolean> | boolean;
  onSkip: () => void;
}) {
  const [name, setName] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  return (
    <div className="sheet-backdrop name-prompt-backdrop" onMouseDown={onSkip}>
      <form
        className="quick-log name-prompt"
        onMouseDown={(event) => event.stopPropagation()}
        onSubmit={async (event) => {
          event.preventDefault();
          if (!name.trim()) return;
          setSaving(true);
          const ok = await onSave(name);
          setSaving(false);
          if (!ok) setError("Hmm, that didn't save. Try again or skip for now.");
        }}
      >
        <div>
          <p className="kicker">BEFORE YOU STAMP</p>
          <h2>What should we call you?</h2>
          <p className="name-prompt-intro">This shows up on the study leaderboard. No email needed.</p>
        </div>
        <label className="log-subject">
          <span>Display name</span>
          <input
            autoFocus
            maxLength={40}
            value={name}
            onChange={(event) => setName(event.target.value)}
            placeholder="e.g. Sleepy Owl"
            required
          />
        </label>
        {error && <p className="name-prompt-error">{error}</p>}
        <button type="submit" disabled={saving}>{saving ? "Saving…" : "That's me"}</button>
        <button type="button" className="name-prompt-skip" onClick={onSkip}>skip for now</button>
      </form>
    </div>
  );
}
